fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function to compute S(k)
    // S(k) = k/2 if k is even
    // S(k) = -(k+1)/2 if k is odd
    // for k >= 0 (S(0) = 0)
    fn prefix_sum(k: i8) -> i8 {
        if k == 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    // For each query (l, r), return S(r) - S(l-1)
    queries
        .into_iter()
        .map(|(l, r)| {
            let s_r = prefix_sum(r);
            let s_l_minus_1 = prefix_sum(l - 1);
            s_r - s_l_minus_1
        })
        .collect()
}